-- Learning cell (learning), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA learning;

CREATE FUNCTION learning.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE learning.learning_challenges (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    challenge_key            text NOT NULL CHECK (length(challenge_key) >= 1),
    track                    text NOT NULL CHECK (length(track) >= 1),
    challenge_type           text NOT NULL CHECK (challenge_type IN ('coding', 'quiz', 'study', 'project', 'competition')),
    provider                 text NOT NULL CHECK (length(provider) >= 1),
    title                    text NOT NULL CHECK (length(title) >= 1),
    description              text,
    instructions             text,
    url                      text,
    difficulty               text,
    estimated_minutes        integer,
    rotation_order           integer NOT NULL DEFAULT 0,
    tags_json                text NOT NULL DEFAULT '[]',
    is_active                integer NOT NULL DEFAULT 1,
    category                 text NOT NULL DEFAULT 'coding',
    is_external              integer NOT NULL DEFAULT 0,
    free_access              integer NOT NULL DEFAULT 0,
    account_required         integer NOT NULL DEFAULT 0,
    access_model             text NOT NULL DEFAULT 'local',
    access_notes             text,
    access_source_url        text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX learning_challenges_legacy ON learning.learning_challenges (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX learning_challenges_category ON learning.learning_challenges (workspace_id, category);
CREATE INDEX learning_challenges_challenge_type ON learning.learning_challenges (workspace_id, challenge_type);

CREATE TABLE learning.learning_challenge_assignments (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    challenge_id             bigint NOT NULL,
    assignment_date          date NOT NULL,
    status                   text NOT NULL DEFAULT 'assigned' CHECK (status IN ('assigned', 'in_progress', 'completed', 'skipped')),
    score_percent            integer,
    time_spent_minutes       double precision,
    solution_url             text,
    notes                    text,
    started_at               timestamptz,
    completed_at             timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, challenge_id) REFERENCES learning.learning_challenges (workspace_id, id)
);
CREATE UNIQUE INDEX learning_challenge_assignments_legacy ON learning.learning_challenge_assignments (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX learning_challenge_assignments_challenge_id ON learning.learning_challenge_assignments (workspace_id, challenge_id);
CREATE INDEX learning_challenge_assignments_status ON learning.learning_challenge_assignments (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE learning.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('challenge', 'challenge-assignment')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE learning.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON learning.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['learning_challenges', 'learning_challenge_assignments', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE learning.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE learning.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON learning.%I'
                       ' USING (workspace_id = learning.current_workspace())'
                       ' WITH CHECK (workspace_id = learning.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA learning TO learning_api;
GRANT EXECUTE ON FUNCTION learning.current_workspace() TO learning_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON learning.learning_challenges, learning.learning_challenge_assignments TO learning_api;
GRANT USAGE ON SEQUENCE learning.learning_challenges_id_seq, learning.learning_challenge_assignments_id_seq TO learning_api;
GRANT SELECT, INSERT ON learning.create_keys TO learning_api;
GRANT SELECT, INSERT ON learning.outbox TO learning_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON learning.outbox TO learning_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON learning.outbox TO learning_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA learning TO learning_publisher;
GRANT SELECT ON learning.outbox TO learning_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON learning.outbox TO learning_publisher;
